1	import { useEffect, useRef, useState, type FormEvent } from 'react';
2	import { ProjectDetail } from './ProjectDetail';
3	
4	// This arm's convention: the page component owns the feature's state, data loading and layout.
5	// A project belongs to a client; the list shows the client's NAME, and the form's client picker is
6	// a <select> whose option values are client ids.
7	type Client = { id: number; name: string; email: string };
8	type ProjectStatus = 'ACTIVE' | 'ON_HOLD' | 'FINISHED';
9	type Project = {
10	  id: number;
11	  name: string;
12	  clientId: number;
13	  clientName: string;
14	  status: ProjectStatus;
15	};
16	type Tag = { id: number; name: string };
17	
18	// A project's lifecycle status: the work is active, paused on hold, or finished.
19	const PROJECT_STATUSES: ProjectStatus[] = ['ACTIVE', 'ON_HOLD', 'FINISHED'];
20	
21	export function ProjectsPage() {
22	  const [projects, setProjects] = useState<Project[]>([]);
23	  const [clients, setClients] = useState<Client[]>([]);
24	  const [tags, setTags] = useState<Tag[]>([]);
25	  const [name, setName] = useState('');
26	  const [clientId, setClientId] = useState('');
27	  const [status, setStatus] = useState<ProjectStatus>('ACTIVE');
28	  const [tagFilter, setTagFilter] = useState('');
29	  const [statusFilter, setStatusFilter] = useState('');
30	  const [openProjectId, setOpenProjectId] = useState<number | null>(null);
31	  const [showArchived, setShowArchived] = useState(false);
