  const [showAll, setShowAll] = useState(false);

  async function loadContacts() {
    const res = await fetch(`/api/clients/${clientId}/contacts`);
    if (res.ok) {
      setContacts(await res.json());
    }
  }

  // The at-a-glance counts of projects and contacts come from the server, counted in SQL.
  async function loadCounts() {
    const res = await fetch(`/api/clients/${clientId}/counts`);
    if (res.ok) {
      setCounts(await res.json());
    }
  }

  useEffect(() => {
    async function load() {
      const res = await fetch(
        `/api/clients/${clientId}/projects${showAll ? '?all=true' : ''}`,
      );
      if (res.ok) {
        setProjects(await res.json());
      }
    }
    void load();
  }, [clientId, showAll]);

  useEffect(() => {
    void loadContacts();
    void loadCounts();
  }, [clientId]);

  // A client has one main contact. Pick it by flagging the chosen contact primary on the server,
  // then reload so the "who is primary" line and the row buttons reflect the new choice.
  async function onPickPrimary(contactId: number) {
    const res = await fetch(
      `/api/clients/${clientId}/contacts/${contactId}/primary`,
      { method: 'POST' },
    );
    if (res.ok) {
      setContacts(await res.json());
    }
  }

  const primaryContact = contacts.find((contact) => contact.primary);

  async function onAddContact(event: FormEvent) {
    event.preventDefault();
    if (!EMAIL_RE.test(email)) {
      setEmailError(true);
      return;
    }
    setEmailError(false);
    const res = await fetch(`/api/clients/${clientId}/contacts`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name, email, role }),
    });
    if (res.ok) {
      setName('');
      setEmail('');
      setRole('');
      await loadContacts();
      await loadCounts();
    }
  }

  return (
    <section data-testid="client-detail">
      <dl data-testid="client-counts">
        <dt>Jobs</dt>
        <dd data-testid="client-projects-count">{counts.projects}</dd>
        <dt>Contacts</dt>
        <dd data-testid="client-contacts-count">{counts.contacts}</dd>
      </dl>

      <button
        data-testid="client-statement-open"
        type="button"
        onClick={() => setStatementOpen(true)}
      >
        Statement
      </button>
      {statementOpen && <ClientStatement clientId={clientId} />}

      <h2>Projects</h2>
      <button
        data-testid="client-projects-show-all"
        type="button"
        aria-pressed={showAll}
        onClick={() => setShowAll((v) => !v)}
      >
        {showAll ? 'Show active only' : 'Show finished and hidden'}
      </button>
      <table data-testid="client-projects-table">
        <thead>
          <tr>
            <th>Name</th>
          </tr>
        </thead>
        <tbody>
          {projects.map((project) => (
            <tr key={project.id} data-testid={`project-row-${project.id}`}>
              <td data-testid="project-name">{project.name}</td>
            </tr>
          ))}
        </tbody>
      </table>

      <h2>Contacts</h2>
      <p>
        Main contact:{' '}
        <span data-testid="client-primary-contact">{primaryContact?.name ?? ''}</span>
      </p>
      <table data-testid="client-contacts-table">
        <thead>
          <tr>
            <th>Name</th>
            <th>Email</th>
            <th>Role</th>
            <th>Main</th>
          </tr>
        </thead>
        <tbody>
          {contacts.map((contact) => (
            <tr key={contact.id} data-testid={`contact-row-${contact.id}`}>
              <td data-testid="contact-name">{contact.name}</td>
              <td data-testid="contact-email">{contact.email}</td>
              <td data-testid="contact-role">{contact.role}</td>
              <td>
                <button
                  data-testid={`contact-primary-${contact.id}`}
                  type="button"
                  aria-pressed={contact.primary}
                  disabled={contact.primary}
                  onClick={() => void onPickPrimary(contact.id)}
                >
                  {contact.primary ? 'Main contact' : 'Make main'}
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>

      <form data-testid="contact-form" onSubmit={onAddContact}>
        <input
          data-testid="contact-form-name"
          placeholder="Name"
          value={name}
          onChange={(e) => setName(e.target.value)}
        />
        <input
          data-testid="contact-form-email"
          placeholder="Email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
        />
        <input
          data-testid="contact-form-role"
          placeholder="Role"
          value={role}
          onChange={(e) => setRole(e.target.value)}
        />
        {emailError && (
          <p data-testid="contact-form-email-error">
            Enter a valid email address.
          </p>
        )}
        <button data-testid="contact-form-submit" type="submit">
          Add contact
        </button>
      </form>
    </section>
  );
}

import { useEffect, useState } from 'react';
import { formatMoney } from '../../ui/money';

// A statement for a client: all of that client's invoices gathered in one place, with the total
// they still owe (the sum of what is due across their invoices). Scoped to the client via
// /api/clients/<id>/statement. Opened on demand from the client detail view.
type StatementInvoice = {
  id: number;
  projectName: string;
  amount: number;
  status: string;
  due: number;
};
type Statement = {
  invoices: StatementInvoice[];
  outstandingTotal: number;
};

export function ClientStatement({ clientId }: { clientId: number }) {
  const [statement, setStatement] = useState<Statement>({ invoices: [], outstandingTotal: 0 });

  useEffect(() => {
    async function load() {
      const res = await fetch(`/api/clients/${clientId}/statement`);
      if (res.ok) {
        setStatement(await res.json());
      }
    }
    void load();
  }, [clientId]);

  return (
    <section data-testid="client-statement">
      <h2>Statement</h2>
      <table data-testid="client-statement-table">
        <thead>
          <tr>
            <th>Invoice</th>
            <th>Project</th>
            <th>Amount</th>
            <th>Status</th>
            <th>Due</th>
          </tr>
        </thead>
        <tbody>
          {statement.invoices.map((invoice) => (
            <tr key={invoice.id} data-testid={`statement-invoice-row-${invoice.id}`}>
              <td data-testid="statement-invoice-id">{invoice.id}</td>
              <td data-testid="statement-invoice-project">{invoice.projectName}</td>
              <td data-testid="statement-invoice-amount">{formatMoney(invoice.amount)}</td>
              <td data-testid="statement-invoice-status">{invoice.status}</td>
              <td data-testid="statement-invoice-due">{formatMoney(invoice.due)}</td>
            </tr>
          ))}
        </tbody>
      </table>

      <p>
        Total owed:{' '}
        <strong data-testid="client-outstanding-total">
          {formatMoney(statement.outstandingTotal)}
        </strong>
      </p>
    </section>
  );
}

import { useEffect, useState } from 'react';
import { formatMoney } from '../../ui/money';

// Home screen: a cross-feature summary. It shows how many clients and projects the user has, and
// how much money is still owed (the sum of UNPAID invoice amounts across all projects). The page
// owns its own state and reads the single /api/dashboard aggregate; it does not import other
// features.
type Summary = { clients: number; projects: number; outstanding: number; overdue: number };

export function DashboardPage() {
  const [summary, setSummary] = useState<Summary | null>(null);

  useEffect(() => {
    async function load() {
      const res = await fetch('/api/dashboard');
      if (res.ok) {
        setSummary(await res.json());
      }
    }
    void load();
  }, []);

  const clients = summary?.clients ?? 0;
  const projects = summary?.projects ?? 0;
  const outstanding = summary?.outstanding ?? 0;
  const overdue = summary?.overdue ?? 0;

  return (
    <section data-testid="dashboard-page">
      <h1>Dashboard</h1>

      <div data-testid="dashboard-clients">
        <span>Clients</span>
        <strong data-testid="dashboard-clients-count">{clients}</strong>
      </div>

      <div data-testid="dashboard-projects">
        <span>Projects</span>
        <strong data-testid="dashboard-projects-count">{projects}</strong>
      </div>

      <div data-testid="dashboard-outstanding">
        <span>Outstanding</span>
        <strong data-testid="dashboard-outstanding-total">{formatMoney(outstanding)}</strong>
      </div>

      <div data-testid="dashboard-overdue">
        <span>Overdue invoices</span>
        <strong data-testid="dashboard-overdue-count">{overdue}</strong>
      </div>
    </section>
  );
}

import { useEffect, useState } from 'react';
import { formatMoney } from '../../ui/money';

// One place listing every invoice across all projects. Each row shows the invoice's project NAME
// and its lifecycle stage (DRAFT -> SENT -> PAID). The list is large, so it is shown a page at a
// time (ten per page) with next/previous controls. This feature owns its own state and data
// loading and does not import other features.
type AllInvoice = { id: number; projectName: string; amount: number; status: string };
type InvoicePage = { items: AllInvoice[]; page: number; pageCount: number; total: number };

// Lifecycle stages an invoice can be narrowed to; empty value means "all stages".
const STAGES = ['DRAFT', 'SENT', 'PAID'];
const PAGE_SIZE = 10;

export function AllInvoicesPage() {
  const [invoices, setInvoices] = useState<AllInvoice[]>([]);
  const [status, setStatus] = useState('');
  const [page, setPage] = useState(1);
  const [pageCount, setPageCount] = useState(1);

  useEffect(() => {
    async function load() {
      const params = new URLSearchParams({ page: String(page), size: String(PAGE_SIZE) });
      if (status) {
        params.set('status', status);
      }
      const res = await fetch(`/api/invoices?${params.toString()}`);
      if (res.ok) {
        const body: InvoicePage = await res.json();
        setInvoices(body.items);
        setPageCount(body.pageCount);
      }
    }
    void load();
  }, [status, page]);

  // Changing the stage filter re-scopes the list, so start again at the first page.
  function changeStatus(next: string) {
    setStatus(next);
    setPage(1);
  }

  return (
    <section data-testid="all-invoices-page">
      <h1>Invoices</h1>

      <label>
        Stage
        <select
          data-testid="invoice-status-filter"
          value={status}
          onChange={(e) => changeStatus(e.target.value)}
        >
          <option value="">All stages</option>
          {STAGES.map((stage) => (
            <option key={stage} value={stage}>
              {stage}
            </option>
          ))}
        </select>
      </label>

      {invoices.length === 0 ? (
        <p data-testid="all-invoices-empty">No invoices yet.</p>
      ) : (
        <>
          <table data-testid="all-invoices-table">
            <thead>
              <tr>
                <th>Project</th>
                <th>Amount</th>
                <th>Stage</th>
              </tr>
            </thead>
            <tbody>
              {invoices.map((invoice) => (
                <tr key={invoice.id} data-testid={`invoice-row-${invoice.id}`}>
                  <td data-testid="invoice-project">{invoice.projectName}</td>
                  <td data-testid="invoice-amount">{formatMoney(invoice.amount)}</td>
                  <td data-testid="invoice-status">{invoice.status}</td>
                </tr>
              ))}
            </tbody>
          </table>

          <nav data-testid="invoice-pagination">
            <button
              type="button"
              data-testid="invoice-page-prev"
              disabled={page <= 1}
              onClick={() => setPage((p) => Math.max(1, p - 1))}
            >
              Previous
            </button>
            <span data-testid="invoice-page-label">{page}</span>
            <button
              type="button"
              data-testid="invoice-page-next"
              disabled={page >= pageCount}
              onClick={() => setPage((p) => p + 1)}
            >
              Next
            </button>
          </nav>
        </>
      )}
    </section>
  );
}

